        ('user_organization_memberships', ARRAY['granted_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('user_preferences', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('user_push_subscriptions', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('user_role_assignments', ARRAY['role_id'], 'roles', ARRAY['id'], 'organization_id', 'organization_id'),
        ('user_subscriptions', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_cursors', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_item_events', ARRAY['actor_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_item_reads', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_items', ARRAY['agent_handed_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_items', ARRAY['assignee_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('watchtower_items', ARRAY['resolved_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('worker_pay_assignments', ARRAY['created_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('worker_portal_invitations', ARRAY['accepted_user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('worker_portal_invitations', ARRAY['invited_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('worker_pto', ARRAY['approver_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('worker_pto', ARRAY['rejector_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workers', ARRAY['manager_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workers', ARRAY['user_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workflow_instances', ARRAY['started_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workflow_templates', ARRAY['created_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workflow_templates', ARRAY['updated_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id'),
        ('workflow_versions', ARRAY['created_by_id'], 'users', ARRAY['id'], 'business_unit_id', 'business_unit_id')
        ) AS v(child, child_columns, parent, parent_columns, child_tenant, parent_tenant)
    LOOP
        SELECT string_agg(format('c.%I IS NOT NULL', u.c), ' AND '),
               string_agg(format('p.%I = c.%I', u.p, u.c), ' AND ')
        INTO present, matched
        FROM unnest(k.child_columns, k.parent_columns) AS u(c, p);
        EXECUTE format(
            'SELECT count(*) FROM %I c WHERE %s AND NOT EXISTS (SELECT 1 FROM %I p WHERE %s AND p.%I = c.%I)',
            k.child, present, k.parent, matched, k.parent_tenant, k.child_tenant
        ) INTO found;
        IF found > 0 THEN
            problems := problems || format(E'\n  %s.%s: %s rows refer to a %s row of another tenant',
                k.child, array_to_string(k.child_columns, ', '), found, k.parent);
        END IF;
    END LOOP;
    IF problems <> '' THEN
        RAISE EXCEPTION 'rows refer to records of another tenant, so their foreign keys cannot carry the tenant; nothing was changed:%', problems
            USING HINT = 'Point each reference at a record of the row''s own tenant or clear it, then run the migration again (docs/engineering/backend/data-access.md, "Tenant keys").';
    END IF;
END
$preflight$;

